-- Source: XC_ICIJ_OFFSHORE_NODES_ENTITIES (814344 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: INCORPORATION_DATE/INACTIVATION_DATE/STRUCK_OFF_DATE/
-- DORM_DATE were bare try_to_date() calls -- a pure-digit value would
-- misread as epoch seconds instead of failing safely. No staging model
-- matches this source: this is the third landing copy of the same ICIJ
-- entities data (per the header above), and the one staging model that does
-- exist (models/staging/fed_icij_offshoreleaks_entities) reads a different
-- landing table and doesn't cast incorporation_date either -- so wrapped all
-- four bare casts in place instead. This model stays disabled (drop-list
-- duplicate, see above) -- fixed anyway since it's a landmine either way.

with source as (
    select * from {{ source('ripple_raw', 'XC_ICIJ_OFFSHORE_NODES_ENTITIES') }}
)

select
    NODE_ID as node_id,
    NAME as name,
    ORIGINAL_NAME as original_name,
    FORMER_NAME as former_name,
    JURISDICTION as jurisdiction,
    JURISDICTION_DESCRIPTION as jurisdiction_description,
    COMPANY_TYPE as company_type,
    ADDRESS as address,
    INTERNAL_ID as internal_id,
    {{ stg_date('INCORPORATION_DATE') }} as incorporation_date,
    {{ stg_date('INACTIVATION_DATE') }} as inactivation_date,
    {{ stg_date('STRUCK_OFF_DATE') }} as struck_off_date,
    {{ stg_date('DORM_DATE') }} as dorm_date,
    STATUS as status,
    SERVICE_PROVIDER as service_provider,
    IBCRUC as ibcruc,
    COUNTRY_CODES as country_codes,
    COUNTRIES as countries,
    SOURCEID as sourceid,
    VALID_UNTIL as valid_until,
    NOTE as note
from source
